def parse_metric_row(row: str) -> dict[str, int | None]:
    """
    Parse a comma-separated row with keys: day, errors, latency_ms.

    - `day`: string, converted to int if present
    - `errors`: string, converted to int if present
    - `latency_ms`: string, converted to int if present

    Returns a dictionary mapping keys to their parsed values.
    """
    result = {}

    # Parse day
    day = row.split(",")[0]
    if day:
        try:
            result["day"] = int(day)
        except ValueError:
            result["day"] = None

    # Parse errors
    errors = row.split(",")[1]
    if errors:
        try:
            result["errors"] = int(errors)
        except ValueError:
            result["errors"] = None

    # Parse latency_ms
    latency = row.split(",")[2]
    if latency:
        try:
            result["latency_ms"] = int(latency)
        except ValueError:
            result["latency_ms"] = None

    return result
